package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import java.lang.ref.WeakReference;
final class ContextHelp {
 static WeakReference<LeoActivity> current=new WeakReference<LeoActivity>(null);
 static void open(Context c,String page){String controls="";LeoActivity a=current.get();if(a!=null&&a.hasWindowFocus()){page=a.getClass().getSimpleName();controls=a.helpControls();}c.startActivity(new Intent(c,ContextHelpActivity.class).putExtra("page",page).putExtra("controls",controls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 static String text(String page){if(page==null)page="";if(page.contains("Recorder")||page.contains("Recording"))return L.t("OK pornește sau pune în pauză. Opțiuni salvează, deschide înregistrările și alege calitatea pentru următoarea înregistrare. Închiderea paginii nu oprește o înregistrare activă; folosește Oprește și salvează.");if(page.contains("Messages"))return L.t("În conversație, 5 pregătește răspunsul. Opțiuni oferă căutare, selecție text, fixare, arhivare și filtrare. Trimiterea cere alegerea SIM-ului și confirmare. În editor, soft dreapta șterge.");if(page.contains("Phone")||page.contains("InCall"))return L.t("Sus din număr ajunge la file; stânga/dreapta schimbă fila, Jos revine în listă. Verde alege SIM-ul pentru apel. În apel: Opțiuni pentru microfon, ieșire audio, așteptare și conferință. Serviciile depind de Telecom și operator.");if(page.contains("Bluetooth"))return L.t("Selectează transferul cu OK. În așteptare poți accepta sau refuza primirea. Progresul și starea provin din stiva Bluetooth Android. Trimiterea începe numai după alegerea explicită a dispozitivului.");if(page.contains("GlobalSearch"))return L.t("Scrie termenul din taste; Jos intră în rezultate și OK deschide selecția. Căutarea este locală și limitată: SMS, calendar, fișiere, contacte, notițe, muzică și aplicații. Expeditorii filtrați în Leo nu apar în rezultate.");if(page.contains("Calendar"))return L.t("D-pad mută ziua în calendar; OK deschide ziua. Opțiuni oferă agenda și evenimente noi. Rezultatul unei căutări deschide detaliile evenimentului fără să îl modifice.");if(page.contains("Files"))return L.t("OK deschide folderul sau acțiunile fișierului. 5 marchează fișierele. Opțiuni oferă căutare, copiere și mutare. Partajarea prin Bluetooth cere alegerea dispozitivului și confirmare.");if(page.contains("Music")||page.contains("Media")||page.contains("NowPlaying"))return HelpActivity.TEXT[4];if(page.contains("Main"))return L.t("0: media curentă. 1: căutare globală. 5 scurt: acces rapid. 2–9 lung: apelare rapidă. * schimbă cardul Home, # îl deschide. Meniu scurt deschide meniul global; Meniu lung deschide acest ajutor.");return L.t("Sus/jos mută selecția; listele Leo se derulează circular. OK deschide elementul. Acțiunile softkey sunt scrise în bara de jos. În câmpurile de text, tastele numerice folosesc tastatura Leo, iar soft dreapta șterge. Pentru o aplicație Android, meniul global oferă mouse din taste.");}
}
